package edu.pe.cibertec.saibm.inventario.infrastructure.persistence; import java.util.*; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface HoldJpaRepository extends JpaRepository<HoldJpaEntity,UUID>{@Modifying @Query(value="insert into inventory_holds(id,operation_key,book_id,quantity,expires_at,request_hash,state) values (:id,:key,:book,:quantity,:expires,:hash,:state) on conflict(operation_key) do nothing",nativeQuery=true)int insertIfAbsent(@Param("id")UUID id,@Param("key")String key,@Param("book")String book,@Param("quantity")int quantity,@Param("expires")java.time.Instant expires,@Param("hash")String hash,@Param("state")String state);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select h from HoldJpaEntity h where h.operationKey=:key")Optional<HoldJpaEntity> findForUpdate(@Param("key")String key);}
